-- Settings and setup (S2, docs/design/10-settings-and-setup.md §5).
-- Generated by `prisma migrate dev --create-only`, then edited: `founded_on` is added nullable,
-- backfilled from the first fiscal year (which starts on the founding date, 09 D15), and only then
-- made NOT NULL, so databases that already hold a company (local seeds) migrate too.

-- AlterTable
ALTER TABLE "company" ADD COLUMN     "founded_on" DATE,
ADD COLUMN     "invoice_registered_on" DATE,
ADD COLUMN     "setup_opening_skipped_at" TIMESTAMPTZ(6),
ADD COLUMN     "setup_wallets_skipped_at" TIMESTAMPTZ(6);

-- Backfill: the start of fiscal year 1, or the creation date (JST) when there is no fiscal year.
UPDATE "company" AS c
   SET "founded_on" = COALESCE(
         (SELECT min(fy."start_date") FROM "fiscal_year" AS fy WHERE fy."company_id" = c."id"),
         (c."created_at" AT TIME ZONE 'Asia/Tokyo')::date
       )
 WHERE c."founded_on" IS NULL;

ALTER TABLE "company" ALTER COLUMN "founded_on" SET NOT NULL;

-- AlterTable
ALTER TABLE "wallet" ADD COLUMN     "note" TEXT;
